-- Release groups seen in search results, once per media type and name in any case, with an optional rating every profile of that type scores:
-- 1 Good and 2 Bad add the profile's points, 3 Blocked is never taken automatically. A group typed by hand has not been seen yet.
CREATE TABLE IF NOT EXISTS "ReleaseGroups" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "MediaTypeId" smallint NOT NULL REFERENCES "MediaTypes" ("Id"),
    "Name" varchar(64) NOT NULL CHECK (length(btrim("Name")) > 0 AND "Name" = btrim("Name")),
    "ReleaseGroupRatingId" smallint NULL CHECK ("ReleaseGroupRatingId" BETWEEN 1 AND 3),
    "SeenCount" integer NOT NULL DEFAULT 0 CHECK ("SeenCount" >= 0),
    "LastSeenAt" timestamptz NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "ReleaseGroups_MediaTypeId_Name" ON "ReleaseGroups" ("MediaTypeId", lower("Name"));
